import { headers } from 'next/headers'

type ApiResult =
  | { data: unknown; error: false }
  | { data: null; error: true }

async function fetchDashboardData(origin: string, path: string): Promise<ApiResult> {
  try {
    const response = await fetch(new URL(path, origin))
    if (!response.ok) throw new Error(`Request failed: ${response.status}`)

    return { data: await response.json(), error: false }
  } catch {
    return { data: null, error: true }
  }
}

function DataSection({ title, result }: { title: string; result: ApiResult }) {
  return (
    <section>
      <h3>{title}</h3>
      {result.error ? (
        <p>Unable to load {title.toLowerCase()}.</p>
      ) : (
        <pre>{JSON.stringify(result.data, null, 2) ?? String(result.data)}</pre>
      )}
    </section>
  )
}

export default async function Dashboard() {
  const requestHeaders = await headers()
  const host = requestHeaders.get('host')

  if (!host) return <p>Unable to load dashboard data.</p>

  const protocol = requestHeaders.get('x-forwarded-proto')?.split(',')[0] ??
    (host.startsWith('localhost') || host.startsWith('127.0.0.1') ? 'http' : 'https')
  const origin = `${protocol}://${host}`

  const [analytics, notifications, settings] = await Promise.all([
    fetchDashboardData(origin, '/api/analytics'),
    fetchDashboardData(origin, '/api/notifications'),
    fetchDashboardData(origin, '/api/settings'),
  ])

  return (
    <div>
      <h2>Dashboard Content</h2>
      <DataSection title="Analytics" result={analytics} />
      <DataSection title="Notifications" result={notifications} />
      <DataSection title="Settings" result={settings} />
    </div>
  )
}

